function checkRequest(req, session) {
  if (req.method !== "POST") return "POST で送ってください";
  if (req.origin !== "https://shop.example") return "別のサイトからは受け付けません";
  if (req.token !== session.csrfToken) return "トークンが違います";
  return "OK";
}

console.log(checkRequest({ method: "POST", origin: "https://shop.example", token: "t9" }, { csrfToken: "t9" }));

